const body = $('POST /future-message').first().json.body || {};
const LANGS = { en: { name: 'English', dir: 'ltr', disclosure: 'This is an AI-generated message, not financial advice.' }, ar: { name: 'Arabic', dir: 'rtl', disclosure: 'هذه رسالة من الذكاء الاصطناعي، وليست نصيحة مالية.' } };
const language = LANGS[body.language] ? body.language : 'en';
const SIGNPOSTS = { stepchange: { name: 'StepChange', url: 'https://www.stepchange.org', why: 'Free debt advice' }, citizens_advice: { name: 'Citizens Advice', url: 'https://www.citizensadvice.org.uk', why: 'Free help with bills, benefits and rent' }, moneyhelper: { name: 'MoneyHelper', url: 'https://www.moneyhelper.org.uk', why: 'Free, government-backed money guidance' } };
const f = $('Forecast').first().json;
const fm = $('Forecast with monthly insurance').first().json;
const INST = 62;
const name = (f.persona && f.persona.name) || 'Adam';
const risk = (body.risk && body.risk.shortfall) ? body.risk : (f.risks[0] || null);
const monthOf = (d) => new Date(d + 'T00:00:00Z').toLocaleString('en-GB', { month: 'long', timeZone: 'UTC' });
const billAmount = (n) => { const from = new Date(Date.parse(risk.week + 'T00:00:00Z') - 3 * 864e5).toISOString().slice(0, 10); let fb = null; for (const d of f.days) for (const e of d.events) if (e.name === n && e.amount < 0) { const hit = { name: n, amount: -e.amount, date: d.date }; if (d.date >= from && d.date <= risk.firstDay) return hit; if (!fb) fb = hit; } return fb || { name: n }; };
const OPTIONS = {};
if (risk) {
  OPTIONS.save_weekly = { id: 'save_weekly', title: risk.fix, effect: (risk.saveWeekly * risk.weeksUntil >= risk.shortfall) ? 'covers the £' + risk.shortfall + ' gap' : 'makes the gap smaller', apply: null };
  const rm = (fm.risks || [])[0];
  OPTIONS.monthly_insurance = { id: 'monthly_insurance', title: 'Ask the insurer to let you pay the car insurance monthly (about £' + INST + ' a month, usually a bit dearer overall)', effect: rm ? 'the gap shrinks from £' + risk.shortfall + ' to £' + rm.shortfall : 'no short week at all', apply: { billChanges: { 'Car insurance (annual)': INST } } };
}
const facts = { name, today: f.today, current_balance: Math.round(f.currentBalance), income_typical_week: Math.round(f.income.typical), income_low_week: Math.round(f.income.low),
  risk: risk ? { week_start: risk.week, month: monthOf(risk.firstDay), first_short_day: risk.firstDay, shortfall: risk.shortfall, reason: risk.reason, bills: (risk.bills || []).map(billAmount), fix: risk.fix } : null,
  OPTIONS: Object.fromEntries(Object.entries(OPTIONS).map(([k, o]) => [k, { id: o.id, title: o.title, effect: o.effect }])), signposts: SIGNPOSTS };
const CACHE = {"en":"This is an AI-generated message, not financial advice. Hi Adam, it's you, from January. The first week of January was hard. Rent and the yearly car insurance came out together. In the slow weeks, we were £143 short. Two things would have helped. Saving £16 a week, starting now, for nine weeks. Or paying the car insurance monthly instead. Citizens Advice can help for free. Open the app, and let's talk it through.","ar":"هذه رسالة من الذكاء الاصطناعي، وليست نصيحة مالية. مرحبًا آدم، أنا أنتَ، من شهر يناير. كان الأسبوع الأول من يناير صعبًا. خرج الإيجار وتأمين السيارة السنوي معًا. وفي الأسابيع الهادئة، كان ينقصنا مئة وثلاثة وأربعون جنيهًا. شيئان كانا سيساعداننا: أن ندّخر ستة عشر جنيهًا كل أسبوع، من الآن ولمدة تسعة أسابيع. أو أن ندفع تأمين السيارة شهريًا بدلًا من دفعة واحدة. منظمة Citizens Advice تساعد مجانًا. افتح التطبيق، ولنتحدث معًا."};
const writerFacts = facts.risk ? { name, month: facts.risk.month, shortfall_in_slow_weeks: facts.risk.shortfall, bills: facts.risk.bills, income_low_week: facts.income_low_week, income_typical_week: facts.income_typical_week, OPTIONS: facts.OPTIONS, signposts: Object.values(SIGNPOSTS).map(s => s.name) } : null;
const shell = { language, dir: LANGS[language].dir, caller_label: 'Future You · ' + (facts.risk ? facts.risk.month : ''), disclosure_text: LANGS[language].disclosure, risk: facts.risk };
return [{ json: { demo_mode: body.demo_mode === true || !facts.risk, language, name, facts: writerFacts, shell, cache: CACHE, langs: LANGS,
  writer_body: { model: 'claude-sonnet-5-5', max_tokens: 1024, thinking: { type: 'between_tools' },
    system: "You write a short voice message from the user's future self, a couple of months ahead. It will be read aloud by a text-to-speech voice, so write for the ear.\n\nINPUT: a FACTS JSON block computed by code: the user's first name, the month the money runs short, the shortfall in slow weeks, the bills that cause it (with amounts), low vs typical weekly pay, OPTIONS (each with a pre-computed effect) and signposts.\n\nRULES\n1. Use ONLY numbers, dates, names and amounts that appear in FACTS. Never calculate, round differently, estimate or invent a figure. If a number is not in FACTS, leave it out.\n2. Start with this exact sentence: \"This is an AI-generated message, not financial advice.\"\n3. Then speak as the user's future self: \"Hi {name}, it's you, from {month}.\" Warm, calm, on their side. Never blame, shame or frighten. No \"you should have\".\n4. Say what happens in plain words: which bills land together, and that in slow weeks it leaves you short by the shortfall.\n5. Say 1 or 2 things that would have helped, chosen only from OPTIONS, with their effect.\n6. End with: free help exists, name one service from FACTS.signposts, and \"open the app, and let's talk it through\". Say \"talk it through\" only once.\n7. Plain English, reading age 9. Sentences under 15 words. No jargon. Write money as £ followed by digits (e.g. £143). Write dates as words (\"the fourth of January\").\n8. 55 to 75 words total. No lists, no emojis, no stage directions.\n9. Never recommend any financial product, lender, credit, loan, overdraft or investment.\n\nOUTPUT JSON only, no code fences:\n{\"script_en\": \"...\", \"option_ids_used\": [\"save_weekly\"]}".split('{name}').join(name).split('{month}').join(facts.risk ? facts.risk.month : ''),
    messages: [{ role: 'user', content: 'FACTS: ' + JSON.stringify(writerFacts) }] } } }];

const d = $input.first().json;
return [{ json: { ...d.shell, text: d.cache[d.language] || d.cache.en, text_en: d.cache.en, audio: null,
  audio_url: '/audio/adam_' + d.language + '_future_message.mp3', cached: true, guarded: false } }];

const d = $('Build FACTS').first().json;
const textBlock = ($input.first().json.content || []).find(b => b.type === 'text') || {};
let out = null;
try { out = JSON.parse((textBlock.text || '').replace(/^\s*```(json)?/, '').replace(/```\s*$/, '')); } catch (e) { out = null; }
const allowed = new Set((JSON.stringify(d.facts).match(/\d+/g) || []).map(n => String(parseInt(n, 10))));
const amounts = (s) => ((s || '').match(/£\s?(\d+)/g) || []).map(m => m.replace(/\D/g, ''));
const DISC = 'This is an AI-generated message, not financial advice.';
let script = out && out.script_en, guarded = false, reason = null;
if (!script) { guarded = true; reason = 'unparseable'; }
else if (amounts(script).some(a => !allowed.has(a))) { guarded = true; reason = 'invented_number'; }
if (guarded) script = d.cache.en;
if (!script.startsWith(DISC)) script = DISC + ' ' + script;
const L = d.langs[d.language];
const translator = "You translate short, spoken financial-coaching messages for text-to-speech.\nTranslate the INPUT text from English into {language_name} ({language_code}).\n\nRULES\n1. Meaning must be identical. Do not add, remove or soften any fact, warning or disclaimer.\n2. Keep every amount and date exactly equal to the source. Write amounts and dates as words the way a native speaker would say them aloud (for Arabic: Modern Standard Arabic; pounds = جنيه إسترليني).\n3. Keep the opening AI disclosure as the first sentence, translated faithfully.\n4. Plain, warm, everyday register a recent arrival would understand. Short sentences. The listener is {name}, a man: use masculine forms.\n5. Keep organisation names (StepChange, Citizens Advice, MoneyHelper) in Latin script, untranslated.\n6. Output only JSON, no code fences: {\"text\": \"...\", \"amounts_preserved\": [\"143\"]}\n   where amounts_preserved lists every money amount you carried over, as digits.".split('{language_name}').join(L.name).split('{language_code}').join(d.language).split('{name}').join(d.name);
return [{ json: { ...d.shell, script_en: script, script_amounts: amounts(script), guarded, guard_reason: reason,
  translate_body: { model: 'claude-sonnet-5-5', max_tokens: 1024, thinking: { type: 'between_tools' }, system: translator,
    messages: [{ role: 'user', content: 'INPUT: ' + script }] } } }];

const g = $('Guard script').first().json;
const d = $('Build FACTS').first().json;
const textBlock = ($input.first().json.content || []).find(b => b.type === 'text') || {};
let out = null;
try { out = JSON.parse((textBlock.text || '').replace(/^\s*```(json)?/, '').replace(/```\s*$/, '')); } catch (e) { out = null; }
const want = [...new Set(g.script_amounts)].sort().join(',');
const got = out ? [...new Set((out.amounts_preserved || []).map(a => String(a).replace(/\D/g, '')))].sort().join(',') : null;
let text = out && out.text, guarded = g.guarded, reason = g.guard_reason;
if (!text || got !== want) { reason = !text ? 'translation_unparseable' : 'translation_amounts_mismatch'; text = d.cache[g.language] || d.cache.en; guarded = true; }
const { translate_body, script_amounts, script_en, ...shell } = g;
return [{ json: { ...shell, text, text_en: g.guarded ? d.cache.en : script_en, guarded, guard_reason: reason } }];

const g = $input.first().json;
if (g.text) return [{ json: { ...g, audio: null, audio_url: null, cached: false } }];
const { translate_body, script_amounts, script_en, ...shell } = g;
return [{ json: { ...shell, text: script_en, text_en: script_en, audio: null, audio_url: null, cached: false } }];

const msg = $('Final message (voice goes after this)').first().json;
const v = $input.first().json || {};
const audio = (typeof v.audio === 'string' && v.audio.length > 100) ? v.audio : null;
return [{ json: { ...msg, audio, audio_mime: audio ? 'audio/mpeg' : null, audio_error: audio ? null : 'voice_unavailable' } }];
